    tcDate: 'Last updated: September 26, 2026',
    tc1t: 'Article 1 — About us', tc1: 'OROLADO is an online trading platform available at orolado.com. For any question, our support team can be reached at any time from the “Help” section of the site.',
    tc2t: 'Article 2 — Nature of the service', tc2: 'OROLADO offers its own indices. These indices do not represent any share, currency or commodity of a real market. Each trade is a fixed-duration position on the movement of the chosen index. It is neither a placement, nor an investment, nor financial advice.',
    tc3t: 'Article 3 — Access conditions', tc3: 'You must be 18 or older and of legal age in your country. Players must check that this type of service is allowed where they are. Only one account is allowed per person, and the information given at registration must be accurate.',
    tc4t: 'Article 4 — How prices move', tc4: 'Prices move continuously according to a random process, with a new quote every 0.25 second. The same price is shown to every player. No result is decided in advance: nobody, including the OROLADO team, can know the next quote.',
    tc5t: 'Article 5 — Trade rules', tc5: 'BUY (CALL): the trade wins if the final price is above the line. SELL (PUT): the trade wins if the final price is below the line. If the final price is exactly on the line, the stake is returned. With the 90% payout the line is the entry price; with ×5, ×10 and ×50 the target to reach is further away (shown on the chart by a gold line and a coloured zone) and the payout is higher. The rules are the same in demo and real mode.',
    tc6t: 'Article 6 — Stakes', tc6: 'The minimum stake is \u2066$\u00a0\u00a01.\u2069 There is no maximum stake and no cap on winnings: your stake is only limited by your balance.',
    tc7t: 'Article 7 — Demo mode', tc7: 'Demo mode uses virtual money with no value that cannot be withdrawn. It lets you practise with exactly the same rules as real mode.',
    tc8t: 'Article 8 — Deposits', tc8: 'Minimum amounts are shown on the deposit screen. A deposit is credited once the payment provider confirms it. Amounts in local currency are converted at the rate shown at the time of deposit.',
    tc9t: 'Article 9 — Bonuses', tc9: 'OROLADO may offer bonuses at its sole discretion. They appear in the history as “Bonus” and follow the same rules as deposits, including Article 10. A bonus obtained by fraud or through several accounts is cancelled.',
    tc10t: 'Article 10 — Withdrawals', tc10: 'Before a withdrawal, total stakes must reach 2 times the total deposits and bonuses received. Minimum withdrawal amounts are shown on the withdrawal screen for each method. Withdrawals are processed as quickly as possible after validation; timing may vary with the payment method. Any provider fees are shown before validation.',
    tc11t: 'Article 11 — Risks', tc11: 'As with any game of chance, a stake can be lost. Winning and losing streaks are part of chance and no gain is guaranteed. OROLADO is entertainment, not a source of income: only play with money you can afford to lose.',
    tc12t: 'Article 12 — Responsible gaming', tc12: 'If gaming becomes a problem, contact us from the “Help” section: we can limit or close your account at your request (self-exclusion). Take breaks, set yourself a limit and never try to “win back” a loss.',
    tc13t: 'Article 13 — Prohibited behaviour', tc13: 'To keep the game fair for everyone, the following are not allowed: multiple accounts, bots and automated programs, exploiting a technical error, and payment fraud. If abuse is found, the gains it produced may be cancelled and the account closed.',
    tc14t: 'Article 14 — Technical incidents', tc14: 'A trade is always settled at the expiry price recorded by our servers, even if the player is disconnected or the page is closed. If that price is unavailable because of a technical incident, the stake is returned.',
    tc15t: 'Article 15 — Personal data', tc15: 'We only keep the data needed to manage the account (identity, contact, operations), for as long as needed for that purpose and for legal obligations. It is never sold. Players can ask to access, correct or delete it from the “Help” section, except data the law requires us to keep.',
    tc16t: 'Article 16 — Suspension and closure', tc16: 'Players can close their account at any time from the “Help” section. If these terms are not respected, OROLADO may suspend an account after review. The legitimate real balance always remains withdrawable under Article 10.',
    tc17t: 'Article 17 — Complaints', tc17: 'Any complaint must first be sent to support from the “Help” section. We undertake to reply as quickly as possible and to seek an amicable solution before any other step.',
    tc18t: 'Article 18 — Changes', tc18: 'These terms may change; the date of the last update is shown at the top of this page. Continuing to use the site after a change means accepting the new version.',
