    txBonus: 'Bonus', seeMore: 'Voir plus',
    tcDate: 'Dernière mise à jour : 26 septembre 2026',
    tc1t: 'Article 1 — Qui nous sommes', tc1: 'OROLADO est une plateforme de trading en ligne, accessible sur orolado.com. Pour toute question, notre support est joignable à tout moment depuis la rubrique « Aide » du site.',
    tc2t: 'Article 2 — Nature du service', tc2: 'OROLADO propose ses propres indices. Ces indices ne représentent aucune action, devise ou matière première d’un marché réel. Chaque trade est une prise de position à durée fixe sur l’évolution de l’indice choisi. Il ne s’agit ni d’un placement, ni d’un investissement, ni d’un conseil financier.',
    tc3t: 'Article 3 — Conditions d’accès', tc3: 'Il faut avoir 18 ans ou plus et l’âge légal dans son pays. Le joueur doit vérifier que ce type de service est autorisé là où il se trouve. Un seul compte est autorisé par personne, et les informations données à l’inscription doivent être exactes.',
    tc4t: 'Article 4 — Formation des cours', tc4: 'Les cours évoluent en continu selon un processus aléatoire, avec une nouvelle cotation toutes les 0,25 seconde. Le même cours est affiché à tous les joueurs. Aucun résultat n’est décidé à l’avance : personne, y compris l’équipe OROLADO, ne peut connaître la cotation suivante.',
    tc5t: 'Article 5 — Règles d’un trade', tc5: 'ACHETER (CALL) : le trade est gagnant si le cours final est au-dessus de la ligne. VENDRE (PUT) : le trade est gagnant si le cours final est en dessous de la ligne. Si le cours final est exactement sur la ligne, la mise est rendue. Avec le gain de 90 %, la ligne est le prix d’entrée ; avec ×5, ×10 et ×50, l’objectif à atteindre est plus éloigné (il est signalé sur le graphique par une ligne dorée et une zone colorée) et le gain plus élevé. Les règles sont identiques en mode démo et en mode réel.',
    tc6t: 'Article 6 — Mises', tc6: 'La mise minimum est de \u2066$\u00a0\u00a01.\u2069 Il n’y a ni mise maximum ni plafond de gain : votre mise est seulement limitée par votre solde.',
    tc7t: 'Article 7 — Mode démo', tc7: 'Le mode démo utilise de l’argent virtuel, sans valeur et non retirable. Il permet de s’entraîner avec exactement les mêmes règles que le mode réel.',
    tc8t: 'Article 8 — Dépôts', tc8: 'Les montants minimums sont affichés dans l’écran de dépôt. Un dépôt est crédité après confirmation par le prestataire de paiement. Les montants en monnaie locale sont convertis au taux affiché au moment du dépôt.',
    tc9t: 'Article 9 — Bonus', tc9: 'OROLADO peut offrir des bonus, à sa seule discrétion. Ils apparaissent dans l’historique sous la mention « Bonus » et suivent les mêmes règles que les dépôts, y compris l’article 10. Un bonus obtenu par fraude ou au moyen de plusieurs comptes est annulé.',
    tc10t: 'Article 10 — Retraits', tc10: 'Avant un retrait, le total des mises doit atteindre 2 fois le total des dépôts et bonus reçus. Les montants minimums de retrait sont affichés dans l’écran de retrait, selon le moyen choisi. Les retraits sont traités dans les meilleurs délais après validation ; le délai peut varier selon le moyen de paiement. Les éventuels frais du prestataire sont indiqués avant validation.',
    tc11t: 'Article 11 — Risques', tc11: 'Comme dans tout jeu de hasard, une mise peut être perdue. Les séries de gains et de pertes font partie du hasard et aucun gain n’est garanti. OROLADO est un divertissement, pas une source de revenus : jouez uniquement avec l’argent que vous pouvez vous permettre de perdre.',
    tc12t: 'Article 12 — Jeu responsable', tc12: 'Si le jeu devient un problème, contactez-nous depuis la rubrique « Aide » : nous pouvons limiter votre compte ou le fermer à votre demande (auto-exclusion). Faites des pauses, fixez-vous une limite et ne cherchez jamais à « récupérer » une perte.',
    tc13t: 'Article 13 — Interdictions', tc13: 'Pour que le jeu reste équitable pour tous, ne sont pas autorisés : les comptes multiples, les robots et programmes automatiques, l’exploitation d’une erreur technique et la fraude au paiement. Si un abus est constaté, les gains qui en proviennent peuvent être annulés et le compte fermé.',
    tc14t: 'Article 14 — Incidents techniques', tc14: 'Un trade est toujours réglé au cours d’expiration enregistré par nos serveurs, même si le joueur est déconnecté ou si sa page est fermée. Si ce cours est indisponible à cause d’un incident technique, la mise est rendue.',
    tc15t: 'Article 15 — Données personnelles', tc15: 'Nous conservons uniquement les données nécessaires à la gestion du compte (identité, contact, opérations), pendant la durée nécessaire à cette gestion et aux obligations légales. Elles ne sont jamais vendues. Le joueur peut demander à les consulter, les corriger ou les supprimer depuis la rubrique « Aide », sauf celles que la loi nous oblige à conserver.',
    tc16t: 'Article 16 — Suspension et fermeture', tc16: 'Le joueur peut fermer son compte à tout moment depuis la rubrique « Aide ». En cas de non-respect des présentes conditions, OROLADO peut suspendre un compte après examen. Le solde réel légitime reste toujours retirable dans le respect de l’article 10.',
    tc17t: 'Article 17 — Réclamations', tc17: 'Toute réclamation doit d’abord être adressée au support depuis la rubrique « Aide ». Nous nous engageons à y répondre dans les plus brefs délais et à rechercher une solution amiable avant toute autre démarche.',
    tc18t: 'Article 18 — Modifications', tc18: 'Ces conditions peuvent évoluer ; la date de la dernière mise à jour figure en haut de cette page. Continuer à utiliser le site après une modification vaut acceptation de la nouvelle version.',
