    tr: { affRevShareLabel: 'Gelir payı', affRevBalLabel: 'Bakiyen', affRevBig: 'Arkadaşlarından OROLADO’nun tuttuğunun %{pct}’ini kazan', affRevSub: 'Arkadaşlarının oynarken kaybettiğinin bir kısmı. {hold} saat içinde ödenir, çek ya da oyna.', affRevS3: 'Onlardan OROLADO’nun tuttuğunun %{pct}’ini kazanırsın — {hold} saat içinde ödenir.', affRevR1: 'Sen: arkadaşların oynadığında OROLADO’nun kazandığının %{pct}’i.', affRevR3: 'Arkadaşın: ilk yatırımında %5 hediye, OROLADO’dan.', affRevSafe: 'OROLADO kaybedemez: yalnızca kazanılmış parayı paylaşırız.', affRevFaq: 'Sık sorulanlar', affRevQ1: 'Ne zaman ödenirim?', affRevA1: '{hold} saat içinde, serbest para olarak: çekersin ya da oynarsın.', affRevQ2: 'Ne kadar kazanırım?', affRevA2: 'Arkadaşlarından OROLADO’nun tuttuğunun %{pct}’i, ömür boyu.', affRevQ3: 'Arkadaşım kazanırsa?', affRevA3: 'Sayacın yükselene kadar bekler. Hiçbir zaman borçlu olmazsın.', affRevQ4: 'Reklam ve video yapabilir miyim?', affRevA4: 'Evet! Sadece kendini davet etmek için sahte hesap açma.', affRevProjTitle: 'Ne kadar kazanabilirsin', affRevProjNote: 'Arkadaşların ne kadar çok oynarsa o kadar kazanırsın. Sınır yok.', affRevActive: 'aktif arkadaş', affRevPerYear: '/yıl' },
    vi: { affRevShareLabel: 'Chia doanh thu', affRevBalLabel: 'Số dư của bạn', affRevBig: 'Nhận {pct}% số tiền OROLADO giữ lại từ bạn bè của bạn', affRevSub: 'Một phần số tiền bạn bè thua khi chơi. Trả trong {hold}h, để rút hoặc để chơi.', affRevS3: 'Bạn nhận {pct}% số tiền OROLADO giữ từ họ — trả trong {hold}h.', affRevR1: 'Bạn: {pct}% số tiền OROLADO kiếm khi bạn bè chơi.', affRevR3: 'Bạn của bạn: quà 5% cho lần nạp đầu, từ OROLADO.', affRevSafe: 'OROLADO không thể lỗ: chúng tôi chỉ chia tiền đã thắng.', affRevFaq: 'Câu hỏi thường gặp', affRevQ1: 'Khi nào tôi được trả?', affRevA1: 'Trong {hold}h, là tiền tự do: rút hoặc chơi.', affRevQ2: 'Tôi kiếm bao nhiêu?', affRevA2: '{pct}% số tiền OROLADO giữ từ bạn bè, trọn đời.', affRevQ3: 'Nếu bạn tôi thắng?', affRevA3: 'Bộ đếm của bạn chờ tăng lại. Bạn không bao giờ nợ gì.', affRevQ4: 'Tôi có thể làm quảng cáo, video không?', affRevA4: 'Có! Chỉ đừng tạo tài khoản giả để tự giới thiệu mình.', affRevProjTitle: 'Bạn có thể kiếm bao nhiêu', affRevProjNote: 'Bạn bè chơi càng nhiều, bạn kiếm càng nhiều. Không giới hạn.', affRevActive: 'bạn bè hoạt động', affRevPerYear: '/năm' },
    id: { affRevShareLabel: 'Bagi hasil', affRevBalLabel: 'Saldomu', affRevBig: 'Dapatkan {pct}% dari yang OROLADO simpan dari temanmu', affRevSub: 'Bagian dari yang temanmu kalah saat bermain. Dibayar dalam {hold}j, untuk ditarik atau dimainkan.', affRevS3: 'Kamu dapat {pct}% dari yang OROLADO simpan dari mereka — dibayar dalam {hold}j.', affRevR1: 'Kamu: {pct}% dari yang OROLADO dapat saat temanmu bermain.', affRevR3: 'Temanmu: hadiah 5% di deposit pertama, dari OROLADO.', affRevSafe: 'OROLADO tak bisa rugi: kami hanya membagi uang yang sudah menang.', affRevFaq: 'Tanya jawab', affRevQ1: 'Kapan saya dibayar?', affRevA1: 'Dalam {hold}j, sebagai uang bebas: tarik atau mainkan.', affRevQ2: 'Berapa saya dapat?', affRevA2: '{pct}% dari yang OROLADO simpan dari temanmu, seumur hidup.', affRevQ3: 'Bagaimana jika temanku menang?', affRevA3: 'Penghitungmu menunggu sampai naik lagi. Kamu tak pernah berutang.', affRevQ4: 'Bolehkah saya buat iklan dan video?', affRevA4: 'Boleh! Jangan buat akun palsu untuk mereferensikan diri sendiri.', affRevProjTitle: 'Berapa kamu bisa dapat', affRevProjNote: 'Makin banyak temanmu bermain, makin banyak kamu dapat. Tanpa batas.', affRevActive: 'teman aktif', affRevPerYear: '/thn' },
