    tr: { defiEx1: 'Örnek 1: her işlemde 10 $ yatırıp üst üste 5 kez kazanırsın → hediye +30 $ ( 10 $ × 3 = 30 $ )', defiEx2: 'Örnek 2: 2 $, 5 $, 3 $, 10 $ ve 4 $ yatırıp 5’ini kazanırsın → en küçük 2 $ → hediye +6 $', affEx1: 'Arkadaşın 20 $ yatırır: o +1 $, sen +1 $ ( ilk yatırımında )', affEx2: 'Diğer günler yine yatırır: sen her seferinde +%5 alırsın.', affEx3: '1.000 $ yatırır → sen +50 $', affEx4: '10.000 $ yatırır → sen +500 $', topMeRank: 'Sen: {r}. sırada, {p} ORO', topMeOut: 'Sen: {p} ORO, yükselmek için devam!', topRule: 'ORO puanı = kazandığın ÷ yatırdığın × 1000. Küçük bahislerle sık kazan, yüksel. Her pazartesi yeni turnuva.', topPrev: 'Geçen hafta', topThis: 'Bu haftaya dön', topPrevTitle: 'Geçen haftanın sonuçları', topPrevMe: 'Son sonucun: {r}. sırada, {p} ORO', topPrevNone: 'Geçen hafta sıralamada değildin.', topEndedBanner: 'Turnuva bitti', defiLostHud: 'Görev kaybedildi, yarın yenisi', bonR1: 'Ne kadar oynarsan çubuğun o kadar dolar, yatırımının +%10’una kadar bakiyene eklenir.', bonR2: 'Bonusu doldurmak için 7 günün var. Haftada bir bonus: yenisi için pazartesiyi bekle.' },
