    ru: { defiEx1: 'Пример 1: ставите по 10 $ и выигрываете 5 раз подряд → подарок +30 $ ( 10 $ × 3 = 30 $ )', defiEx2: 'Пример 2: ставите 2 $, 5 $, 3 $, 10 $ и 4 $, выигрываете все 5 → минимальная 2 $ → подарок +6 $', affEx1: 'Друг вносит 20 $: он +1 $, вы +1 $ ( с первого пополнения )', affEx2: 'В другие дни он снова пополняет: вы получаете +5 % каждый раз.', affEx3: 'Вносит 1 000 $ → вам +50 $', affEx4: 'Вносит 10 000 $ → вам +500 $', topMeRank: 'Вы: {r}-й, {p} ORO', topMeOut: 'Вы: {p} ORO, продолжайте!', topRule: 'Очки ORO = выигрыш ÷ ставки × 1000. Чаще выигрывайте малыми ставками, чтобы подняться. Новый турнир каждый понедельник.', topPrev: 'Прошлая неделя', topThis: 'К этой неделе', topPrevTitle: 'Итоги прошлой недели', topPrevMe: 'Ваш итог: {r}-й, {p} ORO', topPrevNone: 'На прошлой неделе вас не было в рейтинге.', topEndedBanner: 'Турнир завершён', defiLostHud: 'Задание проиграно, новое завтра', bonR1: 'Чем больше играете, тем больше заполняется полоса, до +10 % депозита на баланс.', bonR2: '7 дней, чтобы заполнить бонус. Один бонус в неделю: новый — с понедельника.' },
    de: { defiEx1: 'Beispiel 1: du setzt je 10 $ und gewinnst 5-mal in Folge → Geschenk +30 $ ( 10 $ × 3 = 30 $ )', defiEx2: 'Beispiel 2: du setzt 2 $, 5 $, 3 $, 10 $ und 4 $, gewinnst alle 5 → kleinster 2 $ → Geschenk +6 $', affEx1: 'Dein Freund zahlt 20 $ ein: er +1 $, du +1 $ ( auf die erste Einzahlung )', affEx2: 'An anderen Tagen zahlt er wieder ein: du bekommst jedes Mal +5 %.', affEx3: 'Er zahlt 1.000 $ ein → du +50 $', affEx4: 'Er zahlt 10.000 $ ein → du +500 $', topMeRank: 'Du: Platz {r} mit {p} ORO', topMeOut: 'Du: {p} ORO, weiter so!', topRule: 'ORO-Punkte = Gewinn ÷ Einsatz × 1000. Gewinne oft mit kleinen Einsätzen, um aufzusteigen. Jeden Montag ein neues Turnier.', topPrev: 'Letzte Woche', topThis: 'Zurück zu dieser Woche', topPrevTitle: 'Ergebnisse der letzten Woche', topPrevMe: 'Dein Endergebnis: Platz {r} mit {p} ORO', topPrevNone: 'Letzte Woche warst du nicht platziert.', topEndedBanner: 'Turnier beendet', defiLostHud: 'Challenge verloren, morgen neu', bonR1: 'Je mehr du spielst, desto voller der Balken, bis +10 % deiner Einzahlung aufs Guthaben.', bonR2: '7 Tage, um den Bonus zu füllen. Ein Bonus pro Woche: warte bis Montag für einen neuen.' },
    hi: { defiEx1: 'उदाहरण 1: हर ट्रेड में $10 और लगातार 5 जीत → उपहार +$30 ( $10 × 3 = $30 )', defiEx2: 'उदाहरण 2: $2, $5, $3, $10 और $4, पाँचों जीत → सबसे छोटा $2 → उपहार +$6', affEx1: 'दोस्त $20 जमा करे: उसे +$1, आपको +$1 ( पहली जमा पर )', affEx2: 'दूसरे दिन वह फिर जमा करे: आपको हर बार +5%।', affEx3: '$1,000 जमा → आपको +$50', affEx4: '$10,000 जमा → आपको +$500', topMeRank: 'आप: {r}वें, {p} ORO', topMeOut: 'आप: {p} ORO, आगे बढ़ें!', topRule: 'ORO अंक = जीत ÷ दांव × 1000। छोटे दांवों से अक्सर जीतें और ऊपर जाएँ। हर सोमवार नया टूर्नामेंट।', topPrev: 'पिछला हफ़्ता', topThis: 'इस हफ़्ते पर लौटें', topPrevTitle: 'पिछले हफ़्ते के नतीजे', topPrevMe: 'आपका अंतिम नतीजा: {r}वें, {p} ORO', topPrevNone: 'पिछले हफ़्ते आप सूची में नहीं थे।', topEndedBanner: 'टूर्नामेंट ख़त्म', defiLostHud: 'चुनौती हारी, नई कल', bonR1: 'जितना खेलें, बार उतना भरे, जमा के +10% तक जो बैलेंस में जुड़ता है।', bonR2: 'बोनस भरने के लिए 7 दिन। हफ़्ते में एक बोनस: नए के लिए सोमवार तक रुकें।' }
