  // v2426 — article 22 : un bonus à la fois ; le 1er dépôt d'un ami invité (déjà +5 %) ne compte pas pour le bonus.
  var TC22_TR = {
    fr: 'Une fois par semaine, tu peux activer ton bonus de dépôt. Après l’activation, ton premier dépôt de 100 $ ou plus de la semaine te donne droit à +10 % de ce dépôt. Ce bonus se remplit pendant que tu joues en compte réel, jusqu’à +10 % de ton dépôt. Tu as 7 jours pour le remplir, même si la semaine se termine entre-temps. Chaque bonus reçu s’ajoute instantanément à ton solde, comme un dépôt normal. Un seul bonus à la fois : tant que ton bonus se remplit, tu ne peux pas en activer un autre. Si tu as été invité par un ami, ton tout premier dépôt reçoit déjà +5 % de cadeau : il ne compte pas pour le bonus de la semaine, tes dépôts suivants oui. Comme tous les bonus, il suit l’article 9.',
    en: 'Once a week you can activate your deposit bonus. After activation, your first deposit of $100 or more that week entitles you to +10% of that deposit. The bonus fills up while you play on the real account, up to +10% of your deposit. You have 7 days to fill it, even if the week ends in the meantime. Each bonus received is added instantly to your balance, like a normal deposit. One bonus at a time: while your bonus is filling, you cannot activate another one. If a friend invited you, your very first deposit already gets a +5% gift: it does not count for the weekly bonus, your next deposits do. Like all bonuses, it follows Article 9.',
    es: 'Una vez por semana puedes activar tu bono de depósito. Tras activarlo, tu primer depósito de 100 $ o más de la semana te da derecho a +10 % de ese depósito. El bono se llena mientras juegas en cuenta real, hasta +10 % de tu depósito. Tienes 7 días para llenarlo, aunque la semana termine entretanto. Cada bono recibido se suma al instante a tu saldo, como un depósito normal. Un solo bono a la vez: mientras tu bono se llena, no puedes activar otro. Si un amigo te invitó, tu primer depósito ya recibe un regalo de +5 %: no cuenta para el bono semanal, tus depósitos siguientes sí. Como todos los bonos, sigue el artículo 9.',
    pt: 'Uma vez por semana podes ativar o teu bónus de depósito. Depois de ativado, o teu primeiro depósito de 100 $ ou mais da semana dá direito a +10 % desse depósito. O bónus enche enquanto jogas em conta real, até +10 % do depósito. Tens 7 dias para o encher, mesmo que a semana acabe entretanto. Cada bónus recebido entra instantaneamente no saldo, como um depósito normal. Um bónus de cada vez: enquanto o teu bónus enche, não podes ativar outro. Se um amigo te convidou, o teu primeiro depósito já recebe um presente de +5 %: não conta para o bónus semanal, os depósitos seguintes sim. Como todos os bónus, segue o artigo 9.',
    ar: 'مرة في الأسبوع يمكنك تفعيل بونص الإيداع. بعد التفعيل، أول إيداع لك بقيمة 100$ أو أكثر في الأسبوع يمنحك +10% منه. يمتلئ البونص بينما تلعب بالحساب الحقيقي، حتى +10% من إيداعك. لديك 7 أيام لملئه، حتى لو انتهى الأسبوع في الأثناء. يُضاف كل بونص فورًا إلى رصيدك كإيداع عادي. بونص واحد في كل مرة: ما دام بونصك يمتلئ لا يمكنك تفعيل آخر. إذا دعاك صديق، فإن أول إيداع لك يحصل أصلًا على هدية +5%: لا يُحتسب للبونص الأسبوعي، أما إيداعاتك التالية فنعم. مثل كل البونصات، يخضع للمادة 9.',
    tr: 'Haftada bir kez yatırım bonusunu etkinleştirebilirsin. Etkinleştirdikten sonra haftanın 100 $ veya üzeri ilk yatırımı sana bu yatırımın +%10’u hakkını verir. Bonus gerçek hesapta oynadıkça dolar, yatırımının +%10’una kadar. Doldurmak için 7 günün var, bu arada hafta bitse bile. Her bonus normal bir yatırım gibi anında bakiyene eklenir. Aynı anda tek bonus: bonusun dolarken başka bir bonus etkinleştiremezsin. Bir arkadaşın seni davet ettiyse, ilk yatırımın zaten +%5 hediye alır: haftalık bonusa sayılmaz, sonraki yatırımların sayılır. Tüm bonuslar gibi Madde 9’a tabidir.',
    vi: 'Mỗi tuần một lần bạn có thể kích hoạt thưởng nạp. Sau khi kích hoạt, lần nạp đầu tiên từ 100 $ trong tuần cho bạn quyền nhận +10% khoản nạp đó. Thưởng đầy dần khi bạn chơi tài khoản thật, tối đa +10% khoản nạp. Bạn có 7 ngày để làm đầy, kể cả khi tuần kết thúc giữa chừng. Mỗi khoản thưởng được cộng ngay vào số dư như khoản nạp bình thường. Mỗi lần chỉ một thưởng: khi thưởng đang đầy dần, bạn không thể kích hoạt thưởng khác. Nếu bạn được bạn bè mời, lần nạp đầu tiên đã nhận quà +5%: không tính cho thưởng tuần, các lần nạp sau thì có. Như mọi khoản thưởng, áp dụng Điều 9.',
    id: 'Seminggu sekali kamu bisa mengaktifkan bonus deposit. Setelah aktif, deposit pertamamu $100 atau lebih minggu itu memberi hak +10% dari deposit itu. Bonus terisi saat kamu bermain di akun real, sampai +10% deposit. Kamu punya 7 hari untuk mengisinya, meski minggunya berakhir di tengah jalan. Setiap bonus langsung masuk saldo seperti deposit biasa. Satu bonus dalam satu waktu: selama bonusmu terisi, kamu tidak bisa mengaktifkan bonus lain. Jika kamu diundang teman, deposit pertamamu sudah mendapat hadiah +5%: tidak dihitung untuk bonus mingguan, deposit berikutnya dihitung. Seperti semua bonus, berlaku Pasal 9.',
    ru: 'Раз в неделю можно активировать бонус на депозит. После активации первое пополнение недели от 100 $ даёт право на +10 % от него. Бонус заполняется, пока вы играете на реальном счёте, до +10 % депозита. На заполнение 7 дней, даже если неделя за это время закончится. Каждый бонус мгновенно зачисляется на баланс, как обычное пополнение. Один бонус за раз: пока бонус заполняется, другой активировать нельзя. Если вас пригласил друг, ваше самое первое пополнение уже получает подарок +5 %: оно не учитывается для недельного бонуса, следующие пополнения учитываются. Как и все бонусы, действует статья 9.',
    de: 'Einmal pro Woche kannst du deinen Einzahlungsbonus aktivieren. Danach gibt dir deine erste Einzahlung ab 100 $ in der Woche Anspruch auf +10 % davon. Der Bonus füllt sich, während du auf dem Echtkonto spielst, bis +10 % der Einzahlung. Du hast 7 Tage Zeit, auch wenn die Woche inzwischen endet. Jeder Bonus kommt sofort aufs Guthaben, wie eine normale Einzahlung. Immer nur ein Bonus: solange dein Bonus sich füllt, kannst du keinen anderen aktivieren. Wenn dich ein Freund eingeladen hat, bekommt deine allererste Einzahlung schon +5 % Geschenk: sie zählt nicht für den Wochenbonus, deine nächsten Einzahlungen schon. Wie alle Boni gilt Artikel 9.',
    hi: 'हफ़्ते में एक बार आप जमा बोनस चालू कर सकते हैं। चालू करने के बाद हफ़्ते की पहली $100 या ज़्यादा की जमा पर +10% का हक़ मिलता है। असली खाते में खेलते समय बोनस भरता है, जमा के +10% तक। भरने के लिए 7 दिन, भले ही इस बीच हफ़्ता ख़त्म हो जाए। हर बोनस सामान्य जमा की तरह तुरंत बैलेंस में जुड़ता है। एक समय में एक बोनस: जब तक आपका बोनस भर रहा है, आप दूसरा चालू नहीं कर सकते। अगर किसी दोस्त ने आपको बुलाया है, तो आपकी पहली जमा को पहले ही +5% उपहार मिलता है: वह साप्ताहिक बोनस में नहीं गिनी जाती, अगली जमा गिनी जाती हैं। सभी बोनस की तरह, अनुच्छेद 9 लागू।'
  };
