    m_defiNA: ['Challenge unavailable for now. Try again later.', 'Défi indisponible pour le moment. Réessayez plus tard.', 'Desafío no disponible por ahora. Inténtalo más tarde.', 'Desafio indisponível no momento. Tente mais tarde.', 'التحدي غير متاح حاليًا. حاول لاحقًا.', 'Meydan okuma şu an kullanılamıyor. Daha sonra tekrar dene.', 'Thử thách tạm thời không khả dụng. Hãy thử lại sau.', 'Tantangan belum tersedia. Coba lagi nanti.', 'Испытание сейчас недоступно. Попробуйте позже.', 'Challenge gerade nicht verfügbar. Versuche es später erneut.', 'चुनौती अभी उपलब्ध नहीं है। बाद में कोशिश करें।'],
    m_googleFail: ['Google sign-in failed. Please try again.', 'Connexion Google impossible. Réessayez.', 'No se pudo iniciar sesión con Google. Inténtalo de nuevo.', 'Não foi possível entrar com o Google. Tente novamente.', 'تعذّر تسجيل الدخول عبر Google. حاول مرة أخرى.', 'Google ile giriş yapılamadı. Tekrar dene.', 'Không thể đăng nhập bằng Google. Hãy thử lại.', 'Gagal masuk dengan Google. Coba lagi.', 'Не удалось войти через Google. Попробуйте снова.', 'Anmeldung mit Google fehlgeschlagen. Bitte erneut versuchen.', 'Google से लॉग इन नहीं हो सका। फिर से कोशिश करें।'],
    m_signupFail: ['Sign-up failed. Please try again.', 'Inscription impossible. Réessayez.', 'No se pudo completar el registro. Inténtalo de nuevo.', 'Não foi possível concluir o cadastro. Tente novamente.', 'تعذّر إنشاء الحساب. حاول مرة أخرى.', 'Kayıt tamamlanamadı. Tekrar dene.', 'Không thể đăng ký. Hãy thử lại.', 'Pendaftaran gagal. Coba lagi.', 'Не удалось зарегистрироваться. Попробуйте снова.', 'Registrierung fehlgeschlagen. Bitte erneut versuchen.', 'साइन अप नहीं हो सका। फिर से कोशिश करें।'],
    m_dupSend: ['This same amount was just sent (less than 2 minutes ago). Check your balance before trying again.', 'Ce même montant vient déjà d’être envoyé (il y a moins de 2 minutes). Vérifiez le solde avant de recommencer.', 'Este mismo importe acaba de enviarse (hace menos de 2 minutos). Revisa tu saldo antes de volver a intentarlo.', 'Este mesmo valor acabou de ser enviado (há menos de 2 minutos). Verifique o saldo antes de tentar de novo.', 'تم إرسال المبلغ نفسه للتو (منذ أقل من دقيقتين). تحقّق من رصيدك قبل المحاولة مجددًا.', 'Aynı tutar az önce gönderildi (2 dakikadan kısa süre önce). Tekrar denemeden önce bakiyeni kontrol et.', 'Số tiền này vừa được gửi (chưa đầy 2 phút trước). Hãy kiểm tra số dư trước khi thử lại.', 'Jumlah yang sama baru saja dikirim (kurang dari 2 menit lalu). Periksa saldo sebelum mencoba lagi.', 'Эта же сумма только что отправлена (менее 2 минут назад). Проверьте баланс, прежде чем повторить.', 'Derselbe Betrag wurde gerade gesendet (vor weniger als 2 Minuten). Prüfe dein Guthaben, bevor du es erneut versuchst.', 'यही राशि अभी भेजी गई है (2 मिनट से कम पहले)। दोबारा कोशिश से पहले बैलेंस देखें।'],
    m_refundFail: ['Refund not completed yet (server unreachable). Try again in a moment.', 'Remboursement non passé (base injoignable). Réessayez dans un instant.', 'Reembolso aún no realizado (servidor no disponible). Inténtalo en un momento.', 'Reembolso ainda não feito (servidor indisponível). Tente daqui a pouco.', 'لم يتم الاسترداد بعد (الخادم غير متاح). حاول بعد قليل.', 'İade henüz yapılmadı (sunucuya ulaşılamıyor). Birazdan tekrar dene.', 'Chưa hoàn tiền (máy chủ không phản hồi). Hãy thử lại sau giây lát.', 'Pengembalian belum berhasil (server tidak terjangkau). Coba lagi sebentar.', 'Возврат ещё не выполнен (сервер недоступен). Попробуйте чуть позже.', 'Erstattung noch nicht erfolgt (Server nicht erreichbar). Gleich erneut versuchen.', 'रिफंड अभी नहीं हुआ (सर्वर उपलब्ध नहीं)। थोड़ी देर में कोशिश करें।'],
    m_vaultMissing: ['Real account not available. Please reload the page.', 'Compte réel indisponible. Actualisez la page.', 'Cuenta real no disponible. Recarga la página.', 'Conta real indisponível. Recarregue a página.', 'الحساب الحقيقي غير متاح. أعد تحميل الصفحة.', 'Gerçek hesap kullanılamıyor. Sayfayı yenile.', 'Tài khoản thật không khả dụng. Hãy tải lại trang.', 'Akun riil tidak tersedia. Muat ulang halaman.', 'Реальный счёт недоступен. Обновите страницу.', 'Echtgeldkonto nicht verfügbar. Bitte Seite neu laden.', 'रियल खाता उपलब्ध नहीं। पेज रीलोड करें।'],
