    x_googleAcct: ['This account was created with Google. Tap “Forgot password?” to create your password (code sent by email).', 'Ce compte a été créé avec Google. Touchez « Mot de passe oublié » pour créer votre mot de passe (code reçu par e-mail).', 'Esta cuenta se creó con Google. Toca «¿Olvidaste tu contraseña?» para crear tu contraseña (código por correo).', 'Esta conta foi criada com o Google. Toque em “Esqueceu a senha?” para criar sua senha (código por e-mail).', 'تم إنشاء هذا الحساب عبر Google. اضغط «نسيت كلمة المرور؟» لإنشاء كلمة مرور (يصلك رمز بالبريد).', 'Bu hesap Google ile oluşturuldu. Şifreni oluşturmak için “Şifremi unuttum?” seçeneğine dokun (kod e-postayla gelir).', 'Tài khoản này được tạo bằng Google. Chạm “Quên mật khẩu?” để tạo mật khẩu (mã gửi qua email).', 'Akun ini dibuat dengan Google. Ketuk “Lupa kata sandi?” untuk membuat kata sandi (kode dikirim lewat email).', 'Этот аккаунт создан через Google. Нажмите «Забыли пароль?», чтобы создать пароль (код придёт на e-mail).', 'Dieses Konto wurde mit Google erstellt. Tippe auf „Passwort vergessen?“, um ein Passwort zu erstellen (Code per E-Mail).', 'यह खाता Google से बना है। पासवर्ड बनाने के लिए “पासवर्ड भूल गए?” पर टैप करें (कोड ईमेल पर आएगा)।', '此账户通过 Google 创建。点击“忘记密码？”设置密码（验证码将发送到邮箱）。'],
    x_addrGen: ['Your deposit address is being generated. Please try again in a moment.', 'Adresse de dépôt en cours de génération. Réessayez dans un instant.', 'La dirección de depósito se está generando. Inténtalo en un momento.', 'O endereço de depósito está sendo gerado. Tente novamente em instantes.', 'يجري إنشاء عنوان الإيداع. حاول مجددًا بعد لحظات.', 'Yatırma adresi oluşturuluyor. Birazdan tekrar deneyin.', 'Đang tạo địa chỉ nạp tiền. Vui lòng thử lại sau giây lát.', 'Alamat deposit sedang dibuat. Coba lagi sebentar lagi.', 'Адрес для депозита создаётся. Повторите через минуту.', 'Einzahlungsadresse wird erstellt. Bitte gleich erneut versuchen.', 'जमा पता बनाया जा रहा है। थोड़ी देर में फिर कोशिश करें।', '正在生成充值地址，请稍后重试。'],
