    x_payBlocked: ['Your browser is blocking the payment page. Try Chrome, or turn off your content blocker, then try again.', 'La page de paiement est bloquée par votre navigateur. Essayez avec Chrome, ou désactivez le bloqueur de contenu, puis réessayez.', 'Tu navegador bloquea la página de pago. Prueba con Chrome o desactiva el bloqueador de contenido y vuelve a intentarlo.', 'Seu navegador está bloqueando a página de pagamento. Tente no Chrome ou desative o bloqueador de conteúdo e tente de novo.', 'متصفحك يحظر صفحة الدفع. جرّب Chrome أو أوقف مانع المحتوى ثم حاول مجددًا.', 'Tarayıcın ödeme sayfasını engelliyor. Chrome’u dene veya içerik engelleyiciyi kapatıp tekrar dene.', 'Trình duyệt đang chặn trang thanh toán. Hãy dùng Chrome hoặc tắt trình chặn nội dung rồi thử lại.', 'Browser Anda memblokir halaman pembayaran. Coba Chrome atau matikan pemblokir konten, lalu coba lagi.', 'Браузер блокирует страницу оплаты. Попробуйте Chrome или отключите блокировщик контента и повторите.', 'Dein Browser blockiert die Zahlungsseite. Versuche es mit Chrome oder deaktiviere den Inhaltsblocker und versuche es erneut.', 'आपका ब्राउज़र भुगतान पेज रोक रहा है। Chrome आज़माएँ या कंटेंट ब्लॉकर बंद करके फिर कोशिश करें।', '您的浏览器拦截了支付页面。请使用 Chrome，或关闭内容拦截器后重试。'],
