    x_waveP: ['Please pay with {list}. On the next page, choose your operator and follow the steps.', 'Payez avec {list}. Sur la page suivante, choisissez votre opérateur et suivez les étapes.', 'Paga con {list}. En la página siguiente, elige tu operador y sigue los pasos.', 'Pague com {list}. Na próxima página, escolha sua operadora e siga as etapas.', 'ادفع عبر {list}. في الصفحة التالية، اختر مشغّلك واتبع الخطوات.', '{list} ile öde. Sonraki sayfada operatörünü seç ve adımları izle.', 'Hãy thanh toán bằng {list}. Ở trang sau, chọn nhà mạng và làm theo các bước.', 'Bayar dengan {list}. Di halaman berikutnya, pilih operator Anda dan ikuti langkahnya.', 'Оплатите через {list}. На следующей странице выберите оператора и следуйте шагам.', 'Bitte zahle mit {list}. Wähle auf der nächsten Seite deinen Anbieter und folge den Schritten.', '{list} से भुगतान करें। अगले पेज पर अपना ऑपरेटर चुनें और चरणों का पालन करें।', '请使用 {list} 支付。在下一页选择您的运营商并按步骤操作。'],
